const storyboardText=String.raw`PASTE_THE_EXACT_LAB_3_SCRIPT_STORYBOARD_JSON_HERE`;
if(storyboardText.startsWith('PASTE_')) throw new Error('Paste the exact Lab 3 script-storyboard.json.');
const s=JSON.parse(storyboardText); let fingerprint=0; for(const ch of storyboardText){fingerprint=(fingerprint*31+ch.charCodeAt(0))>>>0;}
return [{json:{storyboard:s,source_fingerprint:`fnv31-${fingerprint.toString(16)}`}}];

const x=$input.first().json, s=x.storyboard; const blockers=[];
if(s.run_id!=='HB-001') blockers.push('run_id_mismatch'); if(s.script_version!=='script-v1') blockers.push('script_version_mismatch'); if(!/^fnv31-[0-9a-f]+$/.test(s.plan_source_fingerprint||'')) blockers.push('missing_plan_source_fingerprint'); if(s.status!=='script_ready') blockers.push('storyboard_not_ready'); if(!Array.isArray(s.beats)||s.beats.length===0) blockers.push('missing_beats'); if(s.beats?.some(b=>!b.beat_id||!b.visual_request||!b.source_ids?.length)) blockers.push('incomplete_beat');
if(blockers.length) return [{json:{run_id:s.run_id||'UNKNOWN',status:'blocked',blockers,source_fingerprint:x.source_fingerprint,external_action_count:0}}];
const continuity_bible={aspect_ratio:'9:16',palette:['#0F5C5E','#F2A23A','#E7D7B7'],setting:'clean fictional office pantry',identity_rule:'no real people, brands, or logos',text_rule:'reserve safe lower-third area'};
const asset_requests=s.beats.map((b,i)=>({asset_id:`S${String(i+1).padStart(2,'0')}`,beat_id:b.beat_id,prompt_version:'visual-v1',visual_request:b.visual_request,source_ids:b.source_ids,continuity_bible_version:'continuity-v1',max_attempts:2,status:'request_ready'}));
return [{json:{run_id:s.run_id,script_version:s.script_version,plan_source_fingerprint:s.plan_source_fingerprint,source_fingerprint:x.source_fingerprint,status:'asset_pack_ready',continuity_bible_version:'continuity-v1',continuity_bible,asset_requests,external_action_count:0}}];
